/**
 * Used for Atlaskit website docs generator for defining a docs tab.
 */
export type DocsTab = {
	/**
	 * The content of the tab.
	 */
	content: React.ReactNode;
	/**
	 * The name of the tab.
	 */
	name: string;
};

/**
 * Used by the website generator to define tabs for a docs page and the order of the tabs.
 */
export type DocsTabs = Array<DocsTab>;

/**
 * A placeholder for a tab generated by the website, used to position that tab within a package's
 * `docs/website-config.tsx` configuration.
 */
export type GeneratedDocsTab = {
	generated: true;
	name: string;
};

/**
 * The ordered tab configuration exported by a package's `docs/website-config.tsx` module.
 */
export type WebsiteDocsTabs = Array<DocsTab | GeneratedDocsTab>;

/**
 * Places a website-generated tab, such as Examples or Code, at this position in a package's
 * documentation tab configuration.
 */
export const generatedTab = (name: string): GeneratedDocsTab => ({ generated: true, name });
